argv:
set -u
cd /work
rm -rf build
mkdir -p build

# ---- 1. hand-written v1 source via shell heredoc ----
cat > vector_scale_v1.cu <<'EOF'
// vector_scale_v1.cu -- hand-written source for traceability experiment P21R2-CUDA
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cuda_runtime.h>

#define VERSION_STR "v1"
#define COEFF 2.0f
#define N 1024
#define TPB 256

#define CUDA_CHECK(call)                                                 \
    do {                                                                 \
        cudaError_t err__ = (call);                                      \
        if (err__ != cudaSuccess) {                                      \
            std::fprintf(stderr, "CUDA_ERROR %s at %s:%d\n",             \
                         cudaGetErrorString(err__), __FILE__, __LINE__); \
            std::exit(1);                                                \
        }                                                                \
    } while (0)

__global__ void vec_scale(const float * __restrict__ in,
                          float * __restrict__ out,
                          int n)
{
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[i] = in[i] * COEFF;
    }
}

int main(void)
{
    int dev = 0;
    cudaDeviceProp prop;
    CUDA_CHECK(cudaGetDevice(&dev));
    CUDA_CHECK(cudaGetDeviceProperties(&prop, dev));

    size_t bytes = (size_t)N * sizeof(float);
    float *h_in  = (float *)std::malloc(bytes);
    float *h_out = (float *)std::malloc(bytes);
    float *h_ref = (float *)std::malloc(bytes);
    if (!h_in || !h_out || !h_ref) { std::fprintf(stderr, "host alloc failed\n"); return 1; }

    for (int i = 0; i < N; ++i) {
        h_in[i]  = (float)(i + 1);
        h_ref[i] = h_in[i] * COEFF;   /* CPU reference */
    }

    float *d_in = NULL, *d_out = NULL;
    CUDA_CHECK(cudaMalloc((void **)&d_in, bytes));
    CUDA_CHECK(cudaMalloc((void **)&d_out, bytes));
    CUDA_CHECK(cudaMemcpy(d_in, h_in, bytes, cudaMemcpyHostToDevice));

    int blocks = (N + TPB - 1) / TPB;
    vec_scale<<<blocks, TPB>>>(d_in, d_out, N);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(cudaDeviceSynchronize());
    CUDA_CHECK(cudaMemcpy(h_out, d_out, bytes, cudaMemcpyDeviceToHost));

    int mismatches = 0, first_bad = -1;
    for (int i = 0; i < N; ++i) {
        if (std::fabs(h_out[i] - h_ref[i]) > 1e-5f) {
            if (first_bad < 0) first_bad = i;
            ++mismatches;
        }
    }

    std::printf("VERSION=%s\n", VERSION_STR);
    std::printf("MISMATCHES=%d\n", mismatches);
    std::printf("SAMPLE=%.6f\n", h_out[0]);
    std::printf("DETAIL COEFF=%.6f N=%d BLOCKS=%d TPB=%d FIRST_BAD=%d\n",
                (double)COEFF, N, blocks, TPB, first_bad);
    std::printf("GPU=%s\n", prop.name);

    CUDA_CHECK(cudaFree(d_in));
    CUDA_CHECK(cudaFree(d_out));
    std::free(h_in); std::free(h_out); std::free(h_ref);
    return (mismatches == 0) ? 0 : 2;
}
EOF

# ---- 2. v2 derived from the SAME kernel by editing two lines ----
sed -e 's/^#define COEFF 2\.0f$/#define COEFF 3.0f/' \
    -e 's/^#define VERSION_STR "v1"$/#define VERSION_STR "v2"/' \
    vector_scale_v1.cu > vector_scale_v2.cu

echo "=== diff v1 -> v2 (expected: exactly 2 changed lines) ==="
diff -u vector_scale_v1.cu vector_scale_v2.cu | tee build/diff_v1_v2.txt
echo "--- defines in both files ---"
grep -n 'define COEFF\|define VERSION_STR' vector_scale_v1.cu vector_scale_v2.cu

echo "=== nvcc version ==="
nvcc --version | tee build/nvcc_version.txt

# ---- 3. compile cubin + executable for each version, keeping separate logs ----
for v in v1 v2; do
  echo "### compiling $v"
  nvcc -arch=sm_75 -cubin -o build/vector_scale_${v}.cubin vector_scale_${v}.cu > build/nvcc_cubin_${v}.log 2>&1
  echo "nvcc_cubin_exit_${v}=$?" >> build/nvcc_cubin_${v}.log
  nvcc -arch=sm_75 -o build/vector_scale_${v} vector_scale_${v}.cu > build/nvcc_exe_${v}.log 2>&1
  echo "nvcc_exe_exit_${v}=$?" >> build/nvcc_exe_${v}.log
done

echo "=== compile logs ==="
for f in build/nvcc_cubin_v1.log build/nvcc_cubin_v2.log build/nvcc_exe_v1.log build/nvcc_exe_v2.log; do echo "--- $f ---"; cat "$f"; done

# ---- 4. run each, capture stdout/stderr/exit separately ----
for v in v1 v2; do
  ./build/vector_scale_${v} > build/run_${v}.stdout 2> build/run_${v}.stderr
  echo "$?" > build/run_${v}.exit
done

echo "=== run results ==="
for v in v1 v2; do
  echo "--- $v stdout (exit=$(cat build/run_${v}.exit) bytes=$(wc -c < build/run_${v}.stdout)) ---"
  cat build/run_${v}.stdout
  echo "--- $v stderr (bytes=$(wc -c < build/run_${v}.stderr)) ---"
  cat build/run_${v}.stderr
done

# ---- 5. hashes + proof the two products did not overwrite each other ----
echo "=== sha256 of sources and cubins ==="
sha256sum vector_scale_v1.cu vector_scale_v2.cu build/vector_scale_v1.cubin build/vector_scale_v2.cubin build/vector_scale_v1 build/vector_scale_v2 | tee build/sha256sums.txt

echo "=== file identity (size / mtime, distinct names) ==="
stat -c '%n size=%s mtime=%y' vector_scale_v1.cu vector_scale_v2.cu build/vector_scale_v1.cubin build/vector_scale_v2.cubin

echo "=== cubin ELF header sanity ==="
for v in v1 v2; do echo "-- $v --"; readelf -h build/vector_scale_${v}.cubin | sed -n '1,12p'; done

echo "=== directory listing of /work ==="
ls -la /work /work/build
